from build import *
L=json.loads((ROOT/'ledger.json').read_text())
code='var records='+json.dumps(L)+''';var out=[];records.forEach(e=>{var s=sketch.find('#'+e.frame,doc)[0];var errors=[],links=[];function walk(l){if(l.name.indexOf('link:')===0)links.push(l.name);if(l.type==='Text'&&l.parent.name==='copy'&&(l.frame.x<0||l.frame.y<0||l.frame.x+l.frame.width>l.parent.frame.width+1||l.frame.y+l.frame.height>l.parent.frame.height+1))errors.push({name:l.name,text:l.text,parent:l.parent.name,f:l.frame,p:l.parent.frame});(l.layers||[]).forEach(walk);}walk(s);var b=s.layers.find(l=>l.name==='body');var max=Math.max.apply(null,b.layers.map(l=>l.frame.y+l.frame.height));var overlay=s.layers.find(l=>l.name==='Sheet'||l.name==='ActionSheet');out.push({id:e.id,app:e.app,frame:s.id,w:s.frame.width,h:s.frame.height,x:s.frame.x,y:s.frame.y,links:Array.from(new Set(links)),bodyBottom:max,bodyHeight:b.frame.height,errors:errors,overlay:overlay?{y:overlay.frame.y,h:overlay.frame.height}:null});});H.out(out);'''
a=run(code,'audit-readback');(ROOT/'audit.json').write_text(json.dumps(a,indent=2));print('Screens',len(a),'geometry failures',sum(x['w']!=390 or x['h']!=844 for x in a),'copy overflows',sum(len(x['errors']) for x in a));print([{'id':x['id'],'app':x['app'],'bottom':x['bodyBottom'],'height':x['bodyHeight']} for x in a if x['bodyBottom']>x['bodyHeight']])
